import type { ReactNode } from "react";

interface StatusMessageProps {
  role?: "status" | "alert";
  children: ReactNode;
}

export default function StatusMessage({ role = "status", children }: StatusMessageProps) {
  return (
    <p role={role} className="rounded-xl border border-gray-200 bg-white px-6 py-5 text-gray-700">
      {children}
    </p>
  );
}
