"use client";

import StatusMessage from "@/components/ui/status-message";

export default function GlobalError({ reset }: { reset: () => void }) {
  return (
    <main className="mx-auto w-full max-w-6xl flex-1 px-4 py-12 sm:px-6">
      <StatusMessage role="alert">데이터를 불러오지 못했어요.</StatusMessage>
      <button
        type="button"
        onClick={reset}
        className="mt-4 rounded-lg bg-gray-950 px-4 py-2 text-sm font-semibold text-white hover:bg-gray-800"
      >
        다시 시도
      </button>
    </main>
  );
}
